pub fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    // Input is assumed non-empty by the problem statement.
    // We produce exactly one output entry per input entry, and each inner Vec is non-empty.
    a.into_iter()
        .map(|s| {
            // Partition into "lines". If splitting yields nothing (e.g., empty string),
            // we still return a non-empty inner list by falling back to the original string.
            let mut parts: Vec<String> = if keepends {
                // Keep line endings by using split_inclusive on '\n'.
                // Note: This keeps '\n' but not other line endings; that's fine per requirements.
                s.split_inclusive('\n').map(|p| p.to_string()).collect()
            } else {
                // Drop '\n' by splitting on it.
                s.split('\n').map(|p| p.to_string()).collect()
            };

            if parts.is_empty() {
                parts.push(s);
            }

            parts
        })
        .collect()
}